while True:
 b=p.stdout.read(buf)
 if len(b)<buf: break
 a=np.frombuffer(b,dtype=np.uint8).astype(np.int16)
 vals.append(float(np.mean(np.abs(a-prev))) if prev is not None else 0.0); prev=a; i+=1
p.wait();
for st in range(0,len(vals),20): print(f'{st:3d}-{min(st+19,len(vals)-1):3d}: '+' '.join(f'{x:4.1f}' for x in vals[st:st+20])); print('low motion <1 runs:'); s=None
for j,x in enumerate(vals):
 if x<1 and s is None:s=j
 if (x>=1 or j==len(vals)-1) and s is not None:
  e=j if x>=1 else j+1
  if e-s>=2: print(s,e,e-s)
  s=None"

